use std::collections::HashMap;

pub fn lookup_score(pairs: &[(&str, i32)], name: &str) -> Option<i32> {
    let mut map = HashMap::new();
    for (k, v) in pairs {
        map.insert(*k, *v);
    }
    map.get(name).copied()
}

