answer_code:
pub fn second_largest(values: &[i32]) -> Option<i32> {
    let mut max: Option<i32> = None;
    let mut second: Option<i32> = None;
    for &v in values {
        match max {
            None => max = Some(v),
            Some(m) if v > m => {
                // 最大値が更新されたら、これまでの最大値が 2 番目になる
                second = Some(m);
                max = Some(v);
            }
            Some(m) if v < m => {
                // 最大値より小さい値は 2 番目の候補
                if second.is_none() || v > second.unwrap() {
                    second = Some(v);
                }
            }
            // v == m (最大値と同じ値の重複) は無視する
            Some(_) => {}
        }
    }
    second
}

